/** 0.23.58 release prep: versions + FALLBACK_PINS + CHANGELOG + release-notes + website + AGENTS.
 *  Generated by .audit/web-modernization/make-bump-58.mjs - every text is embedded, so the
 *  release commit does not depend on local files. Every anchor is checked BEFORE anything is
 *  written; an anchor that does not hit exactly once aborts the script with nothing written.
 *  0.23.57 was refused by the publish gate: its tag stays where it is, its CHANGELOG entry is
 *  marked unpublished and its release-notes entry is renamed to this version. */
import { readFileSync, writeFileSync, readdirSync } from 'node:fs';
const V = '0.23.58';
const PREV = '0.23.57';
const REFUSED = '0.23.57';
const DATE = '2026-11-26';
const PR = "PR#48";
const CI = { tests: 1237, pass: 1236, fail: 0, skipped: 1, run: "45846968514" };
if (!(CI.tests > 0 && CI.tests === CI.pass + CI.skipped && CI.fail === 0 && CI.run)) {
  throw new Error('fill the CI tests/pass/skipped figures and the ci run id first');
}
const FACTS = [`${CI.tests} 个单元测试`, `最新 CI：${CI.pass} 通过 / ${CI.skipped} 跳过`];
const edits = [
  ['CHANGELOG.md', [[`## [${REFUSED}] - ${DATE}`, "## [0.23.58] - 2026-11-26\n\n会话列表:内容与 [0.23.57] 完全相同,另修正一处测试。`0.23.57` 没有发布到 npm——标签推上去之后,发布流程自带的测试门禁里,0.23.56 新增的 REPL 续聊测试等\"第二句话到达模型\"的 30 秒超时,一个包都没有发出去;标签不移动,改以本版发布。\n\n随本版发布的两处会话列表修复:①**同一时刻更新的两个会话谁排前面**——紧接着写入的两个会话文件,修改时间有四成概率完全相同(落在同一个时钟节拍里),此前按随机的会话号排,恢复列表里约每五对就有一对把较旧的排在前面;现在同一节拍内按创建时间分先后。②**\"加载更多\"漏行**——与上一页最后一行落在同一毫秒内、略早的会话,翻页时被跳过;现在翻页按上一页末行在排序列表中的位置接着取。\n\n**测试**:同一天暴露的几条对时序敏感的测试一并加固。那条 REPL 续聊测试的等待上限放宽到 3 分钟,第二句话改为在提示符回来之后才输入;扩展包的真实浏览器测试,启动重试由两次各 20 秒放宽到三次各 30 秒(CI 负载高时 Chrome 来不及开出调试端口)。它们验的都是行为,不是速度。CI 实测 1237(1236 通过 / 1 跳过)。\n\n## [0.23.57] - 2026-11-26(未发布到 npm)\n\n> 这一版被发布门禁拒绝(见 [0.23.58]),npm 上不存在 0.23.57;以下内容原样随 0.23.58 发布。"]]],
  ['website/llms.txt', [
    [`npm 包 @hmharness/cli ${PREV} · 单仓 16 包`, `npm 包 @hmharness/cli ${V} · 单仓 16 包`],
    ['1237 个单元测试 CI 门禁（最新 CI：1236 通过 / 1 跳过）', `${FACTS[0]} CI 门禁（${FACTS[1]}）`],
  ]],
  ['website/llms-full.txt', [
    ['最后更新 2026-11-26，npm 包 @hmharness/cli 0.23.57。', `最后更新 ${DATE}，npm 包 @hmharness/cli ${V}。`],
    [`当前 ${PREV}；`, `当前 ${V}；`],
    ['1237 个单元测试 CI 门禁（最新 CI：1236 通过 / 1 跳过）', `${FACTS[0]} CI 门禁（${FACTS[1]}）`],
  ]],
  ['website/index.html', [
    [`"softwareVersion":"${PREV}"`, `"softwareVersion":"${V}"`],
    ['<b>1237</b><span data-i18n="s3">单元测试(1236 通过/1 跳过)</span>', `<b>${CI.tests}</b><span data-i18n="s3">单元测试(${CI.pass} 通过/${CI.skipped} 跳过)</span>`],
    ["s3: '单元测试(1236 通过/1 跳过)'", `s3: '单元测试(${CI.pass} 通过/${CI.skipped} 跳过)'`],
  ]],
  ['website/faq.html', [
    [`"softwareVersion": "${PREV}"`, `"softwareVersion": "${V}"`],
    ['1237 个单元测试门禁（最新 CI：1236 通过 / 1 跳过）', `${FACTS[0]}门禁（${FACTS[1]}）`],
  ]],
  ['AGENTS.md', [
    ['full unit suite (CI gate; 1237 tests at time of writing)', `full unit suite (CI gate; ${CI.tests} tests at time of writing)`],
  ]],
];
// ---- validate everything in memory first ----
const done = [];
for (const [file, pairs] of edits) {
  let t = readFileSync(file, 'utf8');
  for (const [from, to] of pairs) {
    const n = t.split(from).length - 1;
    if (n !== 1) throw new Error(`${file}: anchor must hit exactly once (hit ${n}): ${from.slice(0, 70)}`);
    t = t.replace(from, () => to);
  }
  done.push([file, t]);
}
const bumped = [];
for (const dir of readdirSync('packages')) {
  const p = `packages/${dir}/package.json`;
  let j;
  try { j = JSON.parse(readFileSync(p, 'utf8')); } catch { continue; }
  let dirty = false;
  if (j.version === PREV) { j.version = V; dirty = true; }
  for (const key of ['dependencies', 'devDependencies']) {
    const deps = j[key]; if (!deps) continue;
    for (const [dep, spec] of Object.entries(deps)) {
      if (dep.startsWith('@hmharness/') && spec === PREV) { deps[dep] = V; dirty = true; }
    }
  }
  if (dirty) bumped.push([p, JSON.stringify(j, null, 2) + '\n']);
}
const rootP = JSON.parse(readFileSync('package.json', 'utf8'));
if (rootP.version === PREV) bumped.push(['package.json', JSON.stringify({ ...rootP, version: V }, null, 2) + '\n']);
if (bumped.length !== 17) throw new Error(`expected 17 package versions bumped (root + 16), got ${bumped.length}`);
const pins = "const FALLBACK_PINS = {\n"
  + `  cli: '${V}', web: '${V}', agent: '${V}', kernel: '${V}',\n`
  + `  sandbox: '${V}', evolution: '${V}', 'domain-ops': '${V}',\n`
  + `  evaluation: '${V}', observability: '${V}', 'domain-harmony': '${V}',\n`
  + `  cognitive: '${V}', environments: '${V}', lsp: '${V}',\n`
  + `  browser: '${V}', extension: '${V}',\n`
  + '};';
for (const inst of ['scripts/install-kaihongos.cjs', 'packages/cli/board/install-kaihongos.cjs']) {
  const s = readFileSync(inst, 'utf8');
  const n = s.replace(/const FALLBACK_PINS = \{[\s\S]*?\};/, pins);
  if (n === s) throw new Error(`${inst}: FALLBACK_PINS not changed`);
  done.push([inst, n]);
}
// the refused version's briefing entry is renamed, not duplicated: nothing was published for it
const rnPath = 'packages/cli/release-notes.json';
const rn = JSON.parse(readFileSync(rnPath, 'utf8'));
const head = rn.notes[0];
if (!head) throw new Error('release-notes.json has no entry');
if (head.v === REFUSED) { head.v = V; head.note = "会话列表: 同一时刻更新的会话按创建时间分先后(此前按随机会话号,约每五对有一对把旧的排前面);「加载更多」不再漏掉与上一页末行同一毫秒的会话(0.23.57 被发布门禁拒绝,内容随本版发布)"; }
else if (head.v !== V) throw new Error(`the first release-notes entry is ${head.v}, expected ${REFUSED} (the refused version) or ${V}`);
if (rn.notes.filter((n) => n.v === V).length !== 1) throw new Error('release-notes.json must carry exactly one entry for ' + V);
done.push([rnPath, JSON.stringify(rn, null, 2) + '\n']);
// ---- all checks passed: write ----
for (const [f, t] of done) writeFileSync(f, t, 'utf8');
for (const [f, t] of bumped) writeFileSync(f, t, 'utf8');
console.log(`release ${V} prepared with CI ${CI.run}: tests ${CI.tests} / pass ${CI.pass} / skipped ${CI.skipped}`);
